#!/usr/bin/env python3
"""Durable mailbox and worker for unattended Codex tasks."""

from __future__ import annotations

import argparse
import base64
import io
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import time
from datetime import datetime, timezone
from uuid import uuid4
import zipfile


TASK_ID_RE = re.compile(r"^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{8}$")
TERMINAL_STATES = {"completed", "failed"}


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def read_json(path: Path) -> dict:
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle)


def write_json_atomic(path: Path, value: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        "w", encoding="utf-8", dir=path.parent, delete=False
    ) as handle:
        json.dump(value, handle, indent=2, ensure_ascii=False)
        handle.write("\n")
        temporary = Path(handle.name)
    os.replace(temporary, path)


class Bridge:
    def __init__(self, config_path: Path):
        self.config = read_json(config_path)
        self.data_dir = Path(self.config["data_dir"]).expanduser().resolve()
        self.tasks_dir = self.data_dir / "tasks"
        self.tasks_dir.mkdir(parents=True, exist_ok=True)
        self.allowed_roots = [
            Path(root).expanduser().resolve()
            for root in self.config.get("allowed_roots", [])
        ]
        self.inspect_allowed_roots = self.allowed_roots + [
            Path(root).expanduser().resolve()
            for root in self.config.get("inspect_allowed_roots", [])
        ]
        self.work_allowed_roots = self.allowed_roots + [
            Path(root).expanduser().resolve()
            for root in self.config.get("work_allowed_roots", [])
        ]
        if not self.inspect_allowed_roots and not self.work_allowed_roots:
            raise ValueError("at least one allowed root must be configured")

    def task_dir(self, task_id: str) -> Path:
        if not TASK_ID_RE.fullmatch(task_id):
            raise ValueError("invalid task ID")
        task_dir = self.tasks_dir / task_id
        if not task_dir.is_dir():
            raise FileNotFoundError(f"unknown task: {task_id}")
        return task_dir

    def validate_cwd(self, raw: str, mode: str) -> Path:
        cwd = Path(raw).expanduser().resolve()
        if not cwd.is_dir():
            raise ValueError(f"working directory does not exist: {cwd}")
        allowed_roots = (
            self.inspect_allowed_roots if mode == "inspect" else self.work_allowed_roots
        )
        if not any(cwd == root or root in cwd.parents for root in allowed_roots):
            raise ValueError(
                f"working directory is outside allowed roots for {mode} mode: {cwd}"
            )
        return cwd

    def submit(self, request: dict) -> dict:
        prompt = request.get("prompt")
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError("prompt must be a non-empty string")
        if len(prompt.encode("utf-8")) > self.config.get("max_prompt_bytes", 200_000):
            raise ValueError("prompt exceeds max_prompt_bytes")
        mode = request.get("mode", "inspect")
        if mode not in {"inspect", "work"}:
            raise ValueError("mode must be inspect or work")
        cwd = self.validate_cwd(request.get("cwd", ""), mode)

        task_id = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ-") + uuid4().hex[:8]
        staging = self.tasks_dir / f".{task_id}.tmp"
        task_dir = self.tasks_dir / task_id
        (staging / "input").mkdir(parents=True)
        (staging / "output").mkdir()

        total_input = 0
        seen_names: set[str] = set()
        for item in request.get("inputs", []):
            name = item.get("name", "")
            if Path(name).name != name or name in seen_names:
                raise ValueError(f"invalid or duplicate input name: {name!r}")
            seen_names.add(name)
            payload = base64.b64decode(item.get("content_base64", ""), validate=True)
            total_input += len(payload)
            if total_input > self.config.get("max_input_bytes", 20_000_000):
                raise ValueError("inputs exceed max_input_bytes")
            (staging / "input" / name).write_bytes(payload)

        normalized = {
            "task_id": task_id,
            "prompt": prompt,
            "cwd": str(cwd),
            "mode": mode,
            "created_at": utc_now(),
            "input_names": sorted(seen_names),
        }
        write_json_atomic(staging / "request.json", normalized)
        status = {
            "task_id": task_id,
            "state": "queued",
            "created_at": normalized["created_at"],
            "updated_at": utc_now(),
        }
        write_json_atomic(staging / "status.json", status)
        os.replace(staging, task_dir)
        return status

    def status(self, task_id: str) -> dict:
        return read_json(self.task_dir(task_id) / "status.json")

    def wait(self, task_id: str, timeout: int) -> dict:
        deadline = time.monotonic() + timeout
        while True:
            status = self.status(task_id)
            if status["state"] in TERMINAL_STATES or time.monotonic() >= deadline:
                return status
            time.sleep(1)

    def queued_tasks(self) -> list[Path]:
        queued = []
        for task_dir in self.tasks_dir.iterdir():
            if task_dir.name.startswith(".") or not task_dir.is_dir():
                continue
            try:
                if read_json(task_dir / "status.json").get("state") == "queued":
                    queued.append(task_dir)
            except (OSError, json.JSONDecodeError):
                continue
        return sorted(queued)

    def run_one(self) -> bool:
        queued = self.queued_tasks()
        if not queued:
            return False
        task_dir = queued[0]
        request = read_json(task_dir / "request.json")
        status = read_json(task_dir / "status.json")
        status.update(state="running", started_at=utc_now(), updated_at=utc_now())
        write_json_atomic(task_dir / "status.json", status)

        command = list(self.config.get("codex_command", ["codex"])) + [
            "exec",
            "--json",
            "--color",
            "never",
            "--cd",
            request["cwd"],
            "--output-last-message",
            str(task_dir / "response.md"),
        ]
        if request["mode"] == "inspect":
            command.extend(["--sandbox", "read-only"])
        else:
            command.extend(["--approve-for-me", "--add-dir", str(task_dir / "output")])
        command.append("-")

        prompt = (
            request["prompt"].rstrip()
            + "\n\nTask exchange directory:\n"
            + f"- Read supplied files from {task_dir / 'input'}\n"
            + f"- Write requested deliverables that do not belong in the repository to {task_dir / 'output'}\n"
            + "- End with a self-contained final response describing the result, verification, and file paths.\n"
        )
        timeout = int(self.config.get("task_timeout_seconds", 3600))
        try:
            with (task_dir / "events.jsonl").open("wb") as stdout, (
                task_dir / "stderr.log"
            ).open("wb") as stderr:
                completed = subprocess.run(
                    command,
                    input=prompt.encode("utf-8"),
                    stdout=stdout,
                    stderr=stderr,
                    timeout=timeout,
                    check=False,
                )
            state = "completed" if completed.returncode == 0 else "failed"
            status.update(state=state, exit_code=completed.returncode)
        except subprocess.TimeoutExpired:
            status.update(state="failed", error=f"task timed out after {timeout} seconds")
        except OSError as exc:
            status.update(state="failed", error=str(exc))
        status.update(finished_at=utc_now(), updated_at=utc_now())
        write_json_atomic(task_dir / "status.json", status)
        return True

    def export(self, task_id: str) -> bytes:
        task_dir = self.task_dir(task_id)
        buffer = io.BytesIO()
        with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as archive:
            for name in ("status.json", "response.md", "events.jsonl", "stderr.log"):
                path = task_dir / name
                if path.is_file():
                    archive.write(path, name)
            output_dir = task_dir / "output"
            for path in output_dir.rglob("*"):
                if path.is_file() and not path.is_symlink():
                    archive.write(path, str(Path("output") / path.relative_to(output_dir)))
        return buffer.getvalue()


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--config",
        type=Path,
        default=Path("~/.config/codex-task-bridge/config.json").expanduser(),
    )
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("submit")
    status = subparsers.add_parser("status")
    status.add_argument("task_id")
    wait = subparsers.add_parser("wait")
    wait.add_argument("task_id")
    wait.add_argument("--timeout", type=int, default=3600)
    export = subparsers.add_parser("export")
    export.add_argument("task_id")
    worker = subparsers.add_parser("worker")
    worker.add_argument("--once", action="store_true")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    bridge = Bridge(args.config)
    try:
        if args.command == "submit":
            request = json.load(sys.stdin)
            print(json.dumps(bridge.submit(request)))
        elif args.command == "status":
            print(json.dumps(bridge.status(args.task_id)))
        elif args.command == "wait":
            print(json.dumps(bridge.wait(args.task_id, args.timeout)))
        elif args.command == "export":
            sys.stdout.buffer.write(bridge.export(args.task_id))
        elif args.command == "worker":
            if args.once:
                bridge.run_one()
            else:
                interval = float(bridge.config.get("poll_interval_seconds", 2))
                while True:
                    if not bridge.run_one():
                        time.sleep(interval)
    except (ValueError, FileNotFoundError, json.JSONDecodeError) as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

